 if(f.id==='connect-form'){for(const k of ['google_url','instagram_url'])if(data[k]&&!safeImage(data[k]))throw Error('Links must use HTTPS');await save({...data,wifi_enabled:f.wifi_enabled.checked});}
 if(f.id==='loyalty-form'){await save({...data,reward_target:Number(data.reward_target),loyalty_enabled:f.loyalty_enabled.checked});}
